/**
 * WidgetHost — renders dynamic widgets for end-user web interfaces.
 * Floating panels are draggable windows rendered in the same React tree
 * to keep playback time synchronized.
 */
import { useCallback, useRef, useState } from 'react'
import type { EventEnvelope, Scene } from '@scenelab/scene-ir'
import { PropertiesPanel } from './PropertiesPanel'
import { SpatialCanvas } from './SpatialCanvas'
import { ThreeCanvas } from './ThreeCanvas'
import { Timeline } from './timeline/Timeline'
import type { UIPanel } from './types'

type WidgetType = UIPanel['type']

export interface WidgetHostProps {
  layout: { panels: UIPanel[] } | null
  scene: Scene
  t?: number
  selectedId?: string | null
  onSelect?: (id: string | null) => void
  onEdit?: (events: EventEnvelope[]) => void
  onRemovePanel?: (id: string) => void
  width?: number
}

function SceneInfoWidget({ scene }: { scene: Scene }) {
  return (
    <div style={{ fontSize: 11, background: '#232326', padding: 8, borderRadius: 4 }}>
      <div>id: {scene.id}</div>
      <div>space: {scene.space}</div>
      <div>camera: {scene.camera.projection.type}</div>
      <div>canvas: {scene.canvas.width}x{scene.canvas.height}</div>
      <div>primitives: {scene.root.children.length}</div>
    </div>
  )
}

const MIN_W = 320
const MIN_H = 200
const DEFAULT_W = 500
const DEFAULT_H = 380
const RESIZE_E = 8
const RESIZE_S = 8
const RESIZE_CORNER = 16

type ResizeDir = 'e' | 's' | 'se'

function DraggableFloating({
  panel,
  children,
  onClose,
  initialX,
  initialY,
  renderWithWidth,
}: {
  panel: UIPanel
  children?: React.ReactNode
  onClose?: (id: string) => void
  initialX: number
  initialY: number
  renderWithWidth?: (width: number) => React.ReactNode
}): JSX.Element {
  const [pos, setPos] = useState({ x: initialX, y: initialY })
  const [size, setSize] = useState({ width: DEFAULT_W, height: DEFAULT_H })
  const [z, setZ] = useState(1)
  const dragRef = useRef<{ startX: number; startY: number; origX: number; origY: number } | null>(null)
  const resizeRef = useRef<{ startX: number; startY: number; startW: number; startH: number; dir: ResizeDir } | null>(null)

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
      dragRef.current = { startX: e.clientX, startY: e.clientY, origX: pos.x, origY: pos.y }
      setZ((prev) => prev + 1000)
    },
    [pos.x, pos.y],
  )

  const onPointerMove = useCallback((e: React.PointerEvent) => {
    const d = dragRef.current
    if (!d) return
    setPos({ x: d.origX + (e.clientX - d.startX), y: d.origY + (e.clientY - d.startY) })
  }, [])

  const onPointerUp = useCallback((e: React.PointerEvent) => {
    dragRef.current = null
    try { (e.target as HTMLElement).releasePointerCapture(e.pointerId) } catch {}
  }, [])

  const onResizeDown = useCallback(
    (e: React.PointerEvent, dir: ResizeDir) => {
      e.stopPropagation()
      ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
      resizeRef.current = { startX: e.clientX, startY: e.clientY, startW: size.width, startH: size.height, dir }
      setZ((prev) => prev + 1000)
    },
    [size.height, size.width],
  )

  const onResizeMove = useCallback((e: React.PointerEvent) => {
    const r = resizeRef.current
    if (!r) return
    const dx = e.clientX - r.startX
    const dy = e.clientY - r.startY
    let newW = r.startW
    let newH = r.startH
    if (r.dir === 'e' || r.dir === 'se') {
      newW = Math.max(MIN_W, r.startW + dx)
    }
    if (r.dir === 's' || r.dir === 'se') {
      newH = Math.max(MIN_H, r.startH + dy)
    }
    setSize({ width: newW, height: newH })
  }, [])

  const onResizeUp = useCallback((e: React.PointerEvent) => {
    if (resizeRef.current) {
      resizeRef.current = null
      try { (e.target as HTMLElement).releasePointerCapture(e.pointerId) } catch {}
    }
  }, [])

  const popOutExternal = useCallback(() => {
    try {
      const url = `${window.location.origin}${window.location.pathname}?view=${panel.type}`
      // Open with current size hint but content will fill window responsively
      const w = Math.round(size.width + 40)
      const h = Math.round(size.height + 60)
      window.open(url, `scenelab-${panel.type}-${panel.id.slice(0, 8)}`, `width=${w},height=${h}`)
      // Remove the inline floating after popping out, if handler provided
      onClose?.(panel.id)
    } catch {}
  }, [panel.id, panel.type, onClose, size.height, size.width])

  // Inner width for widgets: outer width minus panel chrome (border + padding)
  // Outer has 1px border each side, body padding 8 each side
  const innerWidth = Math.max(100, size.width - 18)
  const content = renderWithWidth ? renderWithWidth(innerWidth) : children

  return (
    <div
      style={{
        position: 'fixed',
        left: pos.x,
        top: pos.y,
        zIndex: 50 + z,
        width: size.width,
        height: size.height,
        minWidth: MIN_W,
        minHeight: MIN_H,
        background: '#1e1e20',
        border: '1px solid #444',
        borderRadius: 8,
        boxShadow: '0 8px 32px rgba(0,0,0,0.6)',
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
      }}
      onPointerDown={() => setZ((p) => p + 1)}
      onPointerMove={onResizeMove}
      onPointerUp={onResizeUp}
    >
      <div
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '6px 8px',
          background: '#2a2a2e',
          cursor: 'grab',
          userSelect: 'none',
          borderBottom: '1px solid #333',
          flexShrink: 0,
        }}
      >
        <span style={{ fontSize: 11, fontWeight: 600, color: '#ccc', textTransform: 'uppercase' }}>
          {panel.type} • {panel.id.slice(0, 8)}
        </span>
        <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          <button
            onClick={(e) => { e.stopPropagation(); popOutExternal() }}
            title="Pop out to separate window — drag away from main window, live sync via BroadcastChannel"
            style={{ background: '#2d4a6a', border: '1px solid #3a5a7a', color: '#8ec7ff', cursor: 'pointer', borderRadius: 3, padding: '2px 6px', fontSize: 10 }}
          >
            ↗ Pop-out
          </button>
          <span style={{ fontSize: 10, color: '#666' }}>drag to move</span>
          {onClose && (
            <button
              onClick={() => onClose(panel.id)}
              style={{ background: '#333', border: 'none', color: '#ff8888', cursor: 'pointer', borderRadius: 3, padding: '2px 6px', fontSize: 11 }}
            >
              ✕
            </button>
          )}
        </div>
      </div>
      <div style={{ padding: 8, overflow: 'auto', flex: 1, background: '#1a1a1e', position: 'relative' }}>{content}</div>
      {/* Resize handles — edges and corner, same pointer-capture pattern as drag */}
      <div
        onPointerDown={(e) => onResizeDown(e, 'e')}
        onPointerMove={onResizeMove}
        onPointerUp={onResizeUp}
        style={{
          position: 'absolute',
          top: 0,
          right: 0,
          width: RESIZE_E,
          bottom: RESIZE_CORNER,
          cursor: 'ew-resize',
          touchAction: 'none',
        }}
        aria-label="Resize east"
      />
      <div
        onPointerDown={(e) => onResizeDown(e, 's')}
        onPointerMove={onResizeMove}
        onPointerUp={onResizeUp}
        style={{
          position: 'absolute',
          bottom: 0,
          left: 0,
          height: RESIZE_S,
          right: RESIZE_CORNER,
          cursor: 'ns-resize',
          touchAction: 'none',
        }}
        aria-label="Resize south"
      />
      <div
        onPointerDown={(e) => onResizeDown(e, 'se')}
        onPointerMove={onResizeMove}
        onPointerUp={onResizeUp}
        style={{
          position: 'absolute',
          right: 0,
          bottom: 0,
          width: RESIZE_CORNER,
          height: RESIZE_CORNER,
          cursor: 'nwse-resize',
          touchAction: 'none',
          background: 'linear-gradient(135deg, transparent 45%, #555 45%, #555 55%, #777 55%, #777 65%, transparent 65%)',
          borderTopLeftRadius: 3,
        }}
        aria-label="Resize corner"
        title="Drag to resize"
      />
    </div>
  )
}

export function WidgetHost({ layout, scene, t = 0, selectedId, onSelect, onEdit, onRemovePanel, width = 320 }: WidgetHostProps): JSX.Element {
  if (!layout) return <div style={{ fontSize: 12, color: '#666' }}>No UI layout (standalone)</div>

  const renderPanel = (panel: UIPanel, availWidth?: number) => {
    const w = availWidth ?? width
    const type = panel.type as WidgetType
    switch (type) {
      case 'project':
        return <div style={{ fontSize: 11, color: '#888' }}>Project — {JSON.stringify(panel.props)}</div>
      case 'scene':
        return <SceneInfoWidget scene={scene} />
      case 'outliner':
        return (
          <div style={{ fontSize: 11 }}>
            {scene.root.children.map((c: any) => (
              <div key={c.id} style={{ padding: '2px 0' }}>
                <button onClick={() => onSelect?.(c.id)} style={{ background: 'none', border: 'none', color: selectedId === c.id ? '#8ec7ff' : '#ccc', cursor: 'pointer' }}>
                  {c.word} ({c.id})
                </button>
              </div>
            ))}
          </div>
        )
      case 'scene-view':
        return (
          <div>
            {scene.space === '3d' || scene.camera.projection.type === 'perspective' ? (
              <ThreeCanvas scene={scene} t={t} width={w} editableCamera={true} selectedId={selectedId} onSelect={onSelect} config={{ sessionId: 'demo' }} />
            ) : (
              <SpatialCanvas scene={scene} selectedId={selectedId} onSelect={onSelect} onEdit={onEdit} width={w} t={t} config={{ sessionId: 'demo' }} />
            )}
          </div>
        )
      case 'preview':
        return (
          <div>
            <ThreeCanvas scene={scene} t={t} width={w} editableCamera={false} selectedId={selectedId} onSelect={onSelect} config={{ sessionId: 'demo' }} />
            <div style={{ fontSize: 10, color: '#666', marginTop: 4 }}>Preview — scene camera locked (final output)</div>
          </div>
        )
      case 'properties':
        return <PropertiesPanel scene={scene} selectedId={selectedId ?? null} onEdit={onEdit} config={{ sessionId: 'demo' }} />
      case 'timeline':
        return <Timeline scene={scene} t={t} onChange={() => {}} width={w} onEdit={onEdit} config={{ sessionId: 'demo' }} />
      case 'trace':
        return <div style={{ fontSize: 11, color: '#777' }}>Trace — {scene.id}</div>
      default:
        return <div style={{ fontSize: 11, color: '#666' }}>Unknown: {String(type)}</div>
    }
  }

  const left = layout.panels.filter((p) => p.position === 'left')
  const center = layout.panels.filter((p) => p.position === 'center')
  const right = layout.panels.filter((p) => p.position === 'right')
  const floating = layout.panels.filter((p) => !p.position || p.position === 'floating')

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
        {left.length > 0 && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            <div style={{ fontSize: 10, color: '#888', textTransform: 'uppercase' }}>Left</div>
            {left.map((p) => (
              <div key={p.id} style={{ border: '1px solid #333', borderRadius: 6, padding: 8, minWidth: width }}>
                <div style={{ fontSize: 10, color: '#666', marginBottom: 4 }}>{p.type} ({p.id})</div>
                {renderPanel(p)}
              </div>
            ))}
          </div>
        )}
        {center.length > 0 && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8, flex: 1 }}>
            <div style={{ fontSize: 10, color: '#888', textTransform: 'uppercase' }}>Center</div>
            {center.map((p) => (
              <div key={p.id} style={{ border: '1px solid #333', borderRadius: 6, padding: 8 }}>
                <div style={{ fontSize: 10, color: '#666', marginBottom: 4 }}>{p.type} ({p.id})</div>
                {renderPanel(p)}
              </div>
            ))}
          </div>
        )}
        {right.length > 0 && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            <div style={{ fontSize: 10, color: '#888', textTransform: 'uppercase' }}>Right</div>
            {right.map((p) => (
              <div key={p.id} style={{ border: '1px solid #333', borderRadius: 6, padding: 8, minWidth: width }}>
                <div style={{ fontSize: 10, color: '#666', marginBottom: 4 }}>{p.type} ({p.id})</div>
                {renderPanel(p)}
              </div>
            ))}
          </div>
        )}
      </div>

      {floating.length > 0 && (
        <>
          {floating.map((p, idx) => (
            <DraggableFloating key={p.id} panel={p} onClose={onRemovePanel} initialX={100 + idx * 40} initialY={100 + idx * 40} renderWithWidth={(w) => renderPanel(p, w)} />
          ))}
        </>
      )}
    </div>
  )
}

/**
 * SpatialCanvas — the direct-manipulation widget (docs/foundation.md §5). Controlled
 * component: the host owns `scene`; drags emit typed correction events via `onEdit`.
 * Live drag feedback uses `applyEvent` on a preview copy (no local scene ownership);
 * one consolidated event is emitted on pointer-up.
 *
 * 2D view controls (pan: space+drag, zoom: wheel anchored at cursor) pure logic lives
 * in @scenelab/camera-controls; React wrapper lives here in this widget so
 * camera-controls stays framework-agnostic (no React dependency).
 */
import { useCallback, useEffect, useRef, useState } from 'react'
import type { CorrectionEvent, EventEnvelope, Scene, Vec3 } from '@scenelab/scene-ir'
import { applyEvent, findEntity, resolveScene } from '@scenelab/scene-ir'
import { draw, hitTestScene, pixelsPerUnit, project } from '@scenelab/canvas-preview'
import { worldDeltaFromPixels } from './interaction'
import type { Px, Viewport2DState, Viewport2DDragState } from '@scenelab/camera-controls'
import {
  createInitialViewport2DState,
  createViewport2DDragState,
  updateViewportZoomFromDelta,
  panViewport,
  canvasPxFromClient,
  toBasePx as toBasePxPure,
} from '@scenelab/camera-controls'
import { humanEnvelope, type WidgetConfig } from './types'

// ---------------------------------------------------------------------------
// Display metrics helpers — preserve aspect, resample for DPR, letterbox
// ---------------------------------------------------------------------------

export function getSpatialDisplayMetrics(scene: Scene, cssWidth: number, dpr: number): { cssW: number; cssH: number; bufferW: number; bufferH: number; scale: number } {
  const aspect = scene.canvas.width / scene.canvas.height
  const cssW = cssWidth
  const cssH = cssW / aspect
  const bufferW = Math.round(cssW * dpr)
  const bufferH = Math.round(cssH * dpr)
  const scale = scene.canvas.width === 0 ? 1 : bufferW / scene.canvas.width
  return { cssW, cssH, bufferW, bufferH, scale }
}

/**
 * Map a client point to base (scene) pixels accounting for display scaling and viewport.
 * Pure for unit testing at non-default sizes.
 */
export function mapClientToBase(
  clientX: number,
  clientY: number,
  rect: { left: number; top: number; width: number; height: number },
  bufferW: number,
  bufferH: number,
  sceneW: number,
  sceneH: number,
  viewport: Viewport2DState,
): Px | null {
  if (rect.width === 0 || rect.height === 0) return null
  const dprScaleX = bufferW / rect.width
  const dprScaleY = bufferH / rect.height
  const bufferX = (clientX - rect.left) * dprScaleX
  const bufferY = (clientY - rect.top) * dprScaleY
  const scale = sceneW === 0 ? 1 : bufferW / sceneW
  const sceneX = bufferX / scale
  const sceneY = bufferY / scale
  void bufferH
  void sceneH
  void dprScaleY
  return toBasePxPure({ x: sceneX, y: sceneY }, viewport)
}

// ---------------------------------------------------------------------------
// React controls for SpatialCanvas — lives in this widget, wraps pure camera-controls
// ---------------------------------------------------------------------------

interface UseViewport2DControlsOptions {
  canvasRef: React.RefObject<HTMLCanvasElement>
  minZoom?: number
  maxZoom?: number
  initial?: Viewport2DState
  /** Display-to-scene scale (bufferW / sceneW). Divides buffer coords to scene. */
  scaleFactor?: number
}

function useViewport2DControls(opts: UseViewport2DControlsOptions) {
  const { canvasRef, minZoom = 0.1, maxZoom = 40, initial, scaleFactor = 1 } = opts

  const [viewport, setViewport] = useState<Viewport2DState>(() => initial ?? createInitialViewport2DState())
  const viewportRef = useRef<Viewport2DState>(viewport)
  useEffect(() => {
    viewportRef.current = viewport
  }, [viewport])

  const dragRef = useRef<Viewport2DDragState | null>(null)
  const [isPanning, setIsPanning] = useState(false)
  const [isSpacePressed, setIsSpacePressed] = useState(false)
  const spaceRef = useRef(false)

  // Smooth continuous WASD for 2D
  const keysRef = useRef<Set<string>>(new Set())
  const rafRef = useRef<number | null>(null)
  const lastTimeRef = useRef<number>(performance.now())

  const tick = useCallback(() => {
    const now = performance.now()
    const dt = Math.min(0.1, (now - lastTimeRef.current) / 1000)
    lastTimeRef.current = now
    if (keysRef.current.size === 0) {
      rafRef.current = null
      return
    }
    const speed = (200 / viewportRef.current.zoom) * dt // px/sec scaled by zoom
    let dx = 0
    let dy = 0
    if (keysRef.current.has('w')) dy += speed
    if (keysRef.current.has('s')) dy -= speed
    if (keysRef.current.has('a')) dx += speed
    if (keysRef.current.has('d')) dx -= speed
    if (dx !== 0 || dy !== 0) {
      setViewport((prev) => {
        const next = { pan: { x: prev.pan.x + dx, y: prev.pan.y + dy }, zoom: prev.zoom }
        viewportRef.current = next
        return next
      })
    }
    rafRef.current = requestAnimationFrame(tick)
  }, [])

  const ensureTicking = useCallback(() => {
    if (rafRef.current !== null) return
    lastTimeRef.current = performance.now()
    rafRef.current = requestAnimationFrame(tick)
  }, [tick])

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent): void => {
      if (e.code === 'Space') {
        spaceRef.current = true
        setIsSpacePressed(true)
      }
      const k = e.key.toLowerCase()
      if (['w', 'a', 's', 'd'].includes(k)) {
        const target = e.target as HTMLElement | null
        if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) return
        if (!keysRef.current.has(k)) {
          keysRef.current.add(k)
          ensureTicking()
        }
      }
    }
    const onKeyUp = (e: KeyboardEvent): void => {
      if (e.code === 'Space') {
        spaceRef.current = false
        setIsSpacePressed(false)
      }
      const k = e.key.toLowerCase()
      keysRef.current.delete(k)
    }
    const onBlur = (): void => {
      spaceRef.current = false
      setIsSpacePressed(false)
      keysRef.current.clear()
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current)
        rafRef.current = null
      }
    }
    window.addEventListener('keydown', onKeyDown)
    window.addEventListener('keyup', onKeyUp)
    window.addEventListener('blur', onBlur)
    return () => {
      window.removeEventListener('keydown', onKeyDown)
      window.removeEventListener('keyup', onKeyUp)
      window.removeEventListener('blur', onBlur)
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current)
        rafRef.current = null
      }
      keysRef.current.clear()
    }
  }, [ensureTicking])

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return

    const onWheelNative = (e: WheelEvent): void => {
      e.preventDefault()
      e.stopPropagation()
      const cPxBuffer = canvasPxFromClient(canvas, e.clientX, e.clientY)
      const cPxScene: Px = { x: cPxBuffer.x / scaleFactor, y: cPxBuffer.y / scaleFactor }
      setViewport((prev: Viewport2DState) => {
        const next = { pan: { ...prev.pan }, zoom: prev.zoom }
        updateViewportZoomFromDelta(next, cPxScene, e.deltaY, minZoom, maxZoom)
        viewportRef.current = next
        return next
      })
    }

    canvas.addEventListener('wheel', onWheelNative, { passive: false })
    return () => canvas.removeEventListener('wheel', onWheelNative)
  }, [canvasRef, minZoom, maxZoom, scaleFactor])

  const toBasePx = useCallback(
    (canvasPx: Px): Px => {
      // canvasPx is expected to be in scene space already after dividing by scaleFactor outside
      // but for compat, if caller passes buffer space, we divide
      // The hook's callers that use canvasPxFromClient directly will pass buffer; we normalize
      const scenePx: Px = { x: canvasPx.x / scaleFactor, y: canvasPx.y / scaleFactor }
      return toBasePxPure(scenePx, viewportRef.current)
    },
    [scaleFactor],
  )

  const clientToBasePx = useCallback(
    (clientX: number, clientY: number): Px | null => {
      const canvas = canvasRef.current
      if (!canvas) return null
      const cPxBuffer = canvasPxFromClient(canvas, clientX, clientY)
      const cPxScene: Px = { x: cPxBuffer.x / scaleFactor, y: cPxBuffer.y / scaleFactor }
      return toBasePxPure(cPxScene, viewportRef.current)
    },
    [canvasRef, scaleFactor],
  )

  const onPointerDown = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>): boolean => {
      if (!spaceRef.current) return false
      const canvas = canvasRef.current
      if (!canvas) return false
      const cPxBuffer = canvasPxFromClient(canvas, e.clientX, e.clientY)
      const cPxScene: Px = { x: cPxBuffer.x / scaleFactor, y: cPxBuffer.y / scaleFactor }
      dragRef.current = createViewport2DDragState(viewportRef.current, cPxScene)
      setIsPanning(true)
      return true
    },
    [canvasRef, scaleFactor],
  )

  const onPointerMove = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>): boolean => {
      const drag = dragRef.current
      if (!drag) return false
      const canvas = canvasRef.current
      if (!canvas) return false
      const cPxBuffer = canvasPxFromClient(canvas, e.clientX, e.clientY)
      const cPxScene: Px = { x: cPxBuffer.x / scaleFactor, y: cPxBuffer.y / scaleFactor }
      setViewport((prev: Viewport2DState) => {
        const next = panViewport(prev, drag, cPxScene)
        viewportRef.current = next
        return next
      })
      return true
    },
    [canvasRef, scaleFactor],
  )

  const onPointerUp = useCallback(
    (_e: React.PointerEvent<HTMLCanvasElement>): boolean => {
      if (!dragRef.current) return false
      dragRef.current = null
      setIsPanning(false)
      return true
    },
    [],
  )

  return {
    viewport,
    toBasePx,
    clientToBasePx,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    isPanning,
    isSpacePressed,
  }
}

export interface SpatialCanvasProps {
  scene: Scene
  config?: WidgetConfig
  onEdit?: (events: EventEnvelope[]) => void
  onCommit?: (scene: Scene, trace: EventEnvelope[]) => void
  selectedId?: string | null
  onSelect?: (id: string | null) => void
  /** CSS display width in px — letterboxed to preserve scene aspect, resampled at DPR. */
  width?: number
  /** Scrub time in seconds (default 0). The canvas re-renders the scene at this time. */
  t?: number
}

interface DragState {
  id: string
  startPx: Px // in base (untransformed) screen space (scene pixels)
  startPos: Vec3
}

const constPosition = (scene: Scene, id: string): Vec3 | null => {
  const entity = findEntity(scene.root, id)
  if (!entity) return null
  return entity.transform.position.kind === 'const' ? entity.transform.position.value : null
}

export function SpatialCanvas(props: SpatialCanvasProps): JSX.Element {
  const { scene, config, onSelect } = props
  const onEdit = props.onEdit
  const t = props.t ?? 0
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const [drag, setDrag] = useState<DragState | null>(null)
  const [preview, setPreview] = useState<CorrectionEvent | null>(null)

  // Display sizing — preserve aspect by letterboxing, resample at DPR
  const aspect = scene.canvas.width / scene.canvas.height
  const cssW = props.width ?? scene.canvas.width
  const cssH = cssW / aspect
  const dpr = typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1
  const bufferW = Math.round(cssW * dpr)
  const bufferH = Math.round(cssH * dpr)
  const scaleFactor = scene.canvas.width === 0 ? 1 : bufferW / scene.canvas.width

  // 2D view controls now live in @scenelab/camera-controls, scale-aware
  const {
    viewport,
    clientToBasePx,
    onPointerDown: onViewPointerDown,
    onPointerMove: onViewPointerMove,
    onPointerUp: onViewPointerUp,
    isPanning,
    isSpacePressed,
  } = useViewport2DControls({ canvasRef, scaleFactor })

  const rendered = preview ? applyEvent(scene, preview) : scene

  useEffect(() => {
    const canvas = canvasRef.current
    const ctx = canvas?.getContext('2d')
    if (!canvas || !ctx) return
    // Clear in buffer pixels
    ctx.setTransform(1, 0, 0, 1, 0, 0)
    ctx.clearRect(0, 0, canvas.width, canvas.height)
    const bg = rendered.canvas.background
    if (bg) {
      ctx.fillStyle = `rgba(${Math.round(bg.r * 255)}, ${Math.round(bg.g * 255)}, ${Math.round(bg.b * 255)}, ${bg.a})`
      ctx.fillRect(0, 0, canvas.width, canvas.height)
    }
    ctx.save()
    // Map scene pixels → buffer pixels (includes DPR), then viewport
    ctx.scale(scaleFactor, scaleFactor)
    ctx.translate(viewport.pan.x, viewport.pan.y)
    ctx.scale(viewport.zoom, viewport.zoom)
    const resolved = resolveScene(rendered, t)
    draw(ctx, project(resolved))
    ctx.restore()
  }, [rendered, t, viewport, scaleFactor])

  const onPointerDown = (e: React.PointerEvent<HTMLCanvasElement>): void => {
    const canvas = canvasRef.current
    if (!canvas) return

    // space+drag => view pan (view-only, no correction event) — handled by camera-controls
    if (onViewPointerDown(e)) {
      canvas.setPointerCapture(e.pointerId)
      return
    }

    if (config?.readOnly) return

    const basePx = clientToBasePx(e.clientX, e.clientY)
    if (!basePx) return

    const id = hitTestScene(scene, basePx, t)
    onSelect?.(id)
    if (id) {
      const entity = findEntity(scene.root, id)
      // Locked = visible but not draggable (typical editor: still selectable to allow unlock)
      if (entity?.locked === true) return
      const startPos = constPosition(scene, id)
      if (startPos) {
        setDrag({ id, startPx: basePx, startPos })
        canvas.setPointerCapture(e.pointerId)
      }
    }
  }

  const onPointerMove = (e: React.PointerEvent<HTMLCanvasElement>): void => {
    // View pan has priority
    if (onViewPointerMove(e)) return

    if (!drag) return
    const basePx = clientToBasePx(e.clientX, e.clientY)
    if (!basePx) return
    const ppu = pixelsPerUnit(resolveScene(scene, t))
    const d = worldDeltaFromPixels(basePx.x - drag.startPx.x, basePx.y - drag.startPx.y, ppu)
    setPreview({
      type: 'entity.translate',
      target: drag.id,
      from: drag.startPos,
      to: { x: drag.startPos.x + d.x, y: drag.startPos.y + d.y, z: drag.startPos.z },
    })
  }

  const endDrag = (e: React.PointerEvent<HTMLCanvasElement>): void => {
    if (onViewPointerUp(e)) {
      canvasRef.current?.releasePointerCapture?.(e.pointerId)
      return
    }
    if (drag && preview) onEdit?.([humanEnvelope(preview, config?.sessionId)])
    setDrag(null)
    setPreview(null)
    canvasRef.current?.releasePointerCapture?.(e.pointerId)
  }

  return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', background: '#000', width: cssW, height: cssH, border: '1px solid #ddd', boxSizing: 'content-box', overflow: 'hidden' }}>
      <canvas
        ref={canvasRef}
        width={bufferW}
        height={bufferH}
        style={{
          width: cssW,
          height: cssH,
          touchAction: 'none',
          cursor: isPanning ? 'grabbing' : isSpacePressed ? 'grab' : 'auto',
          overscrollBehavior: 'contain',
          display: 'block',
        }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
      />
    </div>
  )
}

// Re-export for backwards compat; new code should import from @scenelab/camera-controls
export type { Viewport2DState as Viewport2D } from '@scenelab/camera-controls'

/**
 * ThreeCanvas — unified 2D+3D preview widget.
 * - Scene View (editableCamera=true): independent editor camera.
 * - Preview (editableCamera=false): locked to scene's camera.
 */
import { useCallback, useEffect, useRef } from 'react'
import * as THREE from 'three'
import type { ResolvedScene, Scene } from '@scenelab/scene-ir'
import { resolveScene } from '@scenelab/scene-ir'
import { ThreeView } from '@scenelab/three-renderer'
import { clientToNdc, hitTest } from '@scenelab/three-renderer'
import type { ControlsState, DragState } from '@scenelab/camera-controls'
import {
  createInitialState,
  applyToCamera,
  createDragState,
  initFromResolved,
  updateOrbit,
  updatePan,
  updateLook,
  updateZoom,
  moveCameraForward,
  moveCameraStrafe,
} from '@scenelab/camera-controls'

interface UseOrbitControlsOptions {
  canvasRef: React.RefObject<HTMLCanvasElement>
  resolvedRef: React.RefObject<ResolvedScene | null>
  renderRef: React.MutableRefObject<() => void>
  enabled: boolean
}

function useOrbitControls(opts: UseOrbitControlsOptions) {
  const { canvasRef, resolvedRef, renderRef, enabled } = opts

  const controlsRef = useRef<ControlsState>(createInitialState())
  const dragRef = useRef<DragState | null>(null)
  const keysRef = useRef<Set<string>>(new Set())
  const rafRef = useRef<number | null>(null)
  const lastTimeRef = useRef<number>(performance.now())

  const init = useCallback(
    (resolved: ResolvedScene) => {
      initFromResolved(controlsRef.current, resolved)
    },
    [],
  )

  const applyControls = useCallback((camera: THREE.Camera) => {
    applyToCamera(camera, controlsRef.current)
  }, [])

  const tick = useCallback(() => {
    const ctrl = controlsRef.current
    if (!ctrl.initialized) {
      rafRef.current = null
      return
    }
    const now = performance.now()
    const dt = Math.min(0.1, (now - lastTimeRef.current) / 1000)
    lastTimeRef.current = now

    if (keysRef.current.size === 0) {
      rafRef.current = null
      return
    }

    const curPos = (() => {
      const sph = ctrl.spherical
      const tgt = ctrl.target
      const sinPhi = Math.sin(sph.phi)
      const x = sph.radius * sinPhi * Math.sin(sph.theta)
      const y = sph.radius * Math.cos(sph.phi)
      const z = sph.radius * sinPhi * Math.cos(sph.theta)
      return new THREE.Vector3(x, y, z).add(tgt)
    })()
    const forwardDir = new THREE.Vector3().subVectors(ctrl.target, curPos).normalize()
    let rightDir = new THREE.Vector3().crossVectors(forwardDir, new THREE.Vector3(0, 1, 0))
    if (rightDir.lengthSq() < 1e-6) rightDir = new THREE.Vector3().crossVectors(forwardDir, new THREE.Vector3(1, 0, 0))
    rightDir.normalize()

    const speed = Math.max(0.8, ctrl.spherical.radius * 0.6) * dt * 3.5
    let f = 0
    let s = 0
    if (keysRef.current.has('w')) f += speed
    if (keysRef.current.has('s')) f -= speed
    if (keysRef.current.has('a')) s -= speed
    if (keysRef.current.has('d')) s += speed

    if (f !== 0) {
      ctrl.target.addScaledVector(forwardDir, f)
    }
    if (s !== 0) {
      ctrl.target.addScaledVector(rightDir, s)
    }

    if ((f !== 0 || s !== 0) && dragRef.current) {
      const drag = dragRef.current
      if (f !== 0) drag.startTarget.addScaledVector(forwardDir, f)
      if (s !== 0) drag.startTarget.addScaledVector(rightDir, s)
    }

    if (f !== 0 || s !== 0) renderRef.current()

    if (keysRef.current.size > 0) {
      rafRef.current = requestAnimationFrame(tick)
    } else {
      rafRef.current = null
    }
  }, [])

  const ensureTicking = useCallback(() => {
    if (rafRef.current !== null) return
    lastTimeRef.current = performance.now()
    rafRef.current = requestAnimationFrame(tick)
  }, [tick])

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    if (!enabled) return

    const onWheelNative = (e: WheelEvent): void => {
      e.preventDefault()
      e.stopPropagation()
      const ctrl = controlsRef.current
      if (!ctrl.initialized) return
      const isPersp = resolvedRef.current?.camera.projection.type === 'perspective'
      updateZoom(ctrl, e.deltaY, !!isPersp)
      renderRef.current()
    }

    const onKeyDown = (e: KeyboardEvent): void => {
      const key = e.key.toLowerCase()
      if (!['w', 'a', 's', 'd'].includes(key)) return
      const target = e.target as HTMLElement | null
      if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) return
      if (keysRef.current.has(key)) return
      e.preventDefault()
      keysRef.current.add(key)
      ensureTicking()
    }

    const onKeyUp = (e: KeyboardEvent): void => {
      const key = e.key.toLowerCase()
      if (keysRef.current.has(key)) {
        keysRef.current.delete(key)
      }
    }

    canvas.addEventListener('wheel', onWheelNative, { passive: false })
    window.addEventListener('keydown', onKeyDown)
    window.addEventListener('keyup', onKeyUp)
    return () => {
      canvas.removeEventListener('wheel', onWheelNative)
      window.removeEventListener('keydown', onKeyDown)
      window.removeEventListener('keyup', onKeyUp)
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current)
        rafRef.current = null
      }
      keysRef.current.clear()
    }
  }, [canvasRef, resolvedRef, renderRef, enabled, ensureTicking])

  const onPointerDown = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>): void => {
      if (!enabled) return
      const ctrl = controlsRef.current
      if (!ctrl.initialized) return

      const isOrbit = e.button === 2
      const isPan = e.button === 1
      if (!isOrbit && !isPan) return

      e.preventDefault()
      canvasRef.current?.setPointerCapture(e.pointerId)

      dragRef.current = createDragState(ctrl, isOrbit ? 'orbit' : 'pan', e.clientX, e.clientY)
    },
    [canvasRef, enabled],
  )

  const onPointerMove = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>): void => {
      if (!enabled) return
      const drag = dragRef.current
      const ctrl = controlsRef.current
      if (!drag || !ctrl.initialized) return

      const dx = e.clientX - drag.startX
      const dy = e.clientY - drag.startY
      const canvas = canvasRef.current
      const canvasHeight = canvas?.height ?? 720

      if (drag.mode === 'orbit') {
        updateOrbit(ctrl, drag, dx, dy)
        renderRef.current()
      } else if (drag.mode === 'look') {
        updateLook(ctrl, drag, dx, dy)
        renderRef.current()
      } else if (drag.mode === 'pan') {
        const isOrtho = resolvedRef.current?.camera.projection.type === 'orthographic'
        updatePan(ctrl, drag, dx, dy, canvasHeight, !!isOrtho)
        renderRef.current()
      }
    },
    [canvasRef, resolvedRef, renderRef, enabled],
  )

  const onPointerUp = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>): void => {
      if (!enabled) return
      if (dragRef.current) {
        dragRef.current = null
        canvasRef.current?.releasePointerCapture(e.pointerId)
      }
    },
    [canvasRef, enabled],
  )

  const onContextMenu = useCallback((e: React.MouseEvent): void => {
    if (enabled) e.preventDefault()
  }, [enabled])

  return {
    initFromResolved: init,
    applyControls,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onContextMenu,
  }
}

export interface ThreeCanvasProps {
  scene: Scene
  t?: number
  width?: number
  editableCamera?: boolean
  selectedId?: string | null
  onSelect?: (id: string | null) => void
  config?: import('./types').WidgetConfig
}

/**
 * Compute display metrics for ThreeCanvas — preserve aspect by letterboxing,
 * resample buffer at DPR. Mirrors SpatialCanvas helper for symmetry and testing.
 */
export function getThreeDisplayMetrics(scene: Scene, cssWidth: number, dpr: number): { cssW: number; cssH: number; bufferW: number; bufferH: number } {
  const aspect = scene.canvas.width / scene.canvas.height
  const cssW = cssWidth
  const cssH = cssW / aspect
  const bufferW = Math.round(cssW * dpr)
  const bufferH = Math.round(cssH * dpr)
  return { cssW, cssH, bufferW, bufferH }
}

export function ThreeCanvas({ scene, t = 0, width, editableCamera = true, selectedId, onSelect, config }: ThreeCanvasProps): JSX.Element {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const viewRef = useRef<ThreeView | null>(null)
  const resolvedRef = useRef<ResolvedScene | null>(null)
  const renderRef = useRef<() => void>(() => {})

  const { initFromResolved, applyControls, onPointerDown: onOrbitPointerDown, onPointerMove, onPointerUp, onContextMenu } =
    useOrbitControls({
      canvasRef,
      resolvedRef,
      renderRef,
      enabled: editableCamera,
    })

  const renderCurrent = useCallback(() => {
    const view = viewRef.current
    const resolved = resolvedRef.current
    if (!view || !resolved) return
    // Pass selectedId so the view can highlight the node in the viewport
    if (editableCamera) {
      view.render(resolved, selectedId ?? null, applyControls)
    } else {
      view.render(resolved, selectedId ?? null)
    }
  }, [applyControls, editableCamera, selectedId])

  const handleSelectPointerDown = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>): void => {
      if (config?.readOnly) return
      if (!onSelect) return
      // Only left-click selects; right/middle are reserved for orbit/pan
      if (e.button !== 0) return
      const canvas = canvasRef.current
      const view = viewRef.current
      if (!canvas || !view) return

      const rect = canvas.getBoundingClientRect()
      const { ndcX, ndcY } = clientToNdc(e.clientX, e.clientY, rect)

      // Similar to SpatialCanvas's `hitTestScene(scene, pt, t)` — the widget
      // owns the hit-test call and the view just supplies the built scene/camera.
      const hitId = hitTest(view.scene, view.camera, ndcX, ndcY)
      onSelect(hitId)
    },
    [config, onSelect],
  )

  const combinedPointerDown = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>): void => {
      // Orbit handles right (2) and middle (1) when editable
      if (editableCamera && (e.button === 1 || e.button === 2)) {
        onOrbitPointerDown(e)
        return
      }
      if (e.button === 0) {
        handleSelectPointerDown(e)
      }
    },
    [editableCamera, onOrbitPointerDown, handleSelectPointerDown],
  )

  useEffect(() => {
    renderRef.current = renderCurrent
  }, [renderCurrent])

  // Display sizing — letterbox to preserve scene aspect, buffer * DPR for crispness
  const aspect = scene.canvas.width / scene.canvas.height
  const cssW = width ?? scene.canvas.width
  const cssH = cssW / aspect
  const dpr = typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1
  const bufferW = Math.round(cssW * dpr)
  const bufferH = Math.round(cssH * dpr)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const view = new ThreeView(canvas)
    view.setSize(bufferW, bufferH)
    viewRef.current = view
    return () => {
      view.dispose()
      viewRef.current = null
    }
  }, [bufferW, bufferH])

  // Keep renderer size in sync when cssW/buffer changes without remounting
  useEffect(() => {
    if (viewRef.current) {
      viewRef.current.setSize(bufferW, bufferH)
      renderCurrent()
    }
  }, [bufferW, bufferH, renderCurrent])

  useEffect(() => {
    const resolved = resolveScene(scene, t)
    resolvedRef.current = resolved
    if (editableCamera) {
      initFromResolved(resolved)
    }
    renderCurrent()
  }, [scene, t, initFromResolved, renderCurrent, editableCamera])

  // Re-render when selection changes so the highlight updates in the viewport
  useEffect(() => {
    renderCurrent()
  }, [selectedId, renderCurrent])

  const hasSelectionHandler = !!onSelect
  const canvasStyle: React.CSSProperties = {
    width: cssW,
    height: cssH,
    border: '1px solid #333',
    display: 'block',
    touchAction: 'none',
    overscrollBehavior: 'contain',
    cursor: hasSelectionHandler ? 'pointer' : editableCamera ? 'grab' : 'default',
    outline: 'none',
  }

  return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', background: '#000', width: cssW, height: cssH, overflow: 'hidden', boxSizing: 'content-box' }}>
      <canvas
        ref={canvasRef}
        width={bufferW}
        height={bufferH}
        tabIndex={0}
        style={canvasStyle}
        onPointerDown={hasSelectionHandler || editableCamera ? combinedPointerDown : undefined}
        onPointerMove={editableCamera ? onPointerMove : undefined}
        onPointerUp={editableCamera ? onPointerUp : undefined}
        onPointerCancel={editableCamera ? onPointerUp : undefined}
        onContextMenu={onContextMenu}
      />
    </div>
  )
}

