import { describe, it, expect } from 'vitest'
import { sampleScene, resolveScene } from '@scenelab/scene-ir'
import { hitTestScene } from '@scenelab/canvas-preview'
import { createInitialViewport2DState } from '@scenelab/camera-controls'
import { getSpatialDisplayMetrics, mapClientToBase } from './SpatialCanvas'
import { getThreeDisplayMetrics } from './ThreeCanvas'

describe('screen-to-scene mapping at non-default size (§5)', () => {
  const scene = sampleScene() // 1920x1080, circle_1 at world (100,0) → screen (1060,540)
  const viewport = createInitialViewport2DState() // pan 0,0 zoom 1

  it('getSpatialDisplayMetrics preserves aspect and scales buffer with DPR', () => {
    const m1 = getSpatialDisplayMetrics(scene, 320, 1)
    expect(m1.cssW).toBe(320)
    expect(m1.cssH).toBeCloseTo(180, 5)
    expect(m1.bufferW).toBe(320)
    expect(m1.bufferH).toBeCloseTo(180, 0)

    const m2 = getSpatialDisplayMetrics(scene, 400, 2)
    expect(m2.cssW).toBe(400)
    expect(m2.cssH).toBeCloseTo(225, 5)
    expect(m2.bufferW).toBe(800)
    expect(m2.bufferH).toBe(450)
    // Scale is bufferW / sceneW
    expect(m2.scale).toBeCloseTo(800 / 1920, 5)
  })

  it('getThreeDisplayMetrics preserves aspect', () => {
    const m = getThreeDisplayMetrics(scene, 640, 1)
    expect(m.cssW).toBe(640)
    expect(m.cssH).toBeCloseTo(360, 5)
    expect(m.bufferW).toBe(640)
    expect(m.bufferH).toBe(360)
  })

  it('maps client point to scene base correctly at half size (960)', () => {
    const cssW = 960 // half of 1920
    const dpr = 1
    const { bufferW, bufferH } = getSpatialDisplayMetrics(scene, cssW, dpr)
    const rect = { left: 0, top: 0, width: cssW, height: cssW / (scene.canvas.width / scene.canvas.height) }
    // Circle center is at scene (1060,540). In half-size display, client should be at half
    const clientX = (1060 / scene.canvas.width) * rect.width
    const clientY = (540 / scene.canvas.height) * rect.height
    const base = mapClientToBase(clientX, clientY, rect, bufferW, bufferH, scene.canvas.width, scene.canvas.height, viewport)
    expect(base).not.toBeNull()
    expect(base!.x).toBeCloseTo(1060, 0)
    expect(base!.y).toBeCloseTo(540, 0)
    // And hit-testing at that base should find circle_1
    expect(hitTestScene(scene, base!, 0)).toBe('circle_1')
  })

  it('maps client point correctly at 400px width with DPR 2 (non-default)', () => {
    const cssW = 400
    const dpr = 2
    const { bufferW, bufferH } = getSpatialDisplayMetrics(scene, cssW, dpr)
    const rect = { left: 10, top: 20, width: cssW, height: cssW / (scene.canvas.width / scene.canvas.height) }
    // Pick a point offset inside rect
    const sceneX = 1060
    const sceneY = 540
    const clientX = rect.left + (sceneX / scene.canvas.width) * rect.width
    const clientY = rect.top + (sceneY / scene.canvas.height) * rect.height
    const base = mapClientToBase(clientX, clientY, rect, bufferW, bufferH, scene.canvas.width, scene.canvas.height, viewport)
    expect(base).not.toBeNull()
    expect(base!.x).toBeCloseTo(sceneX, 0)
    expect(base!.y).toBeCloseTo(sceneY, 0)
    expect(hitTestScene(scene, base!, 0)).toBe('circle_1')
    // Miss far away
    const missBase = mapClientToBase(rect.left + 5, rect.top + 5, rect, bufferW, bufferH, scene.canvas.width, scene.canvas.height, viewport)
    expect(hitTestScene(scene, missBase!, 0)).toBeNull()
  })

  it('letterboxing: same scene point maps consistently across sizes', () => {
    for (const cssW of [320, 500, 800, 960]) {
      const { bufferW, bufferH } = getSpatialDisplayMetrics(scene, cssW, 1)
      const rect = { left: 0, top: 0, width: cssW, height: bufferH } // rect.height = cssH since dpr1
      const clientX = (960 / scene.canvas.width) * rect.width // center X (world 0)
      const clientY = (540 / scene.canvas.height) * rect.height // center Y
      const base = mapClientToBase(clientX, clientY, rect, bufferW, bufferH, scene.canvas.width, scene.canvas.height, viewport)!
      expect(base.x).toBeCloseTo(960, 0)
      expect(base.y).toBeCloseTo(540, 0)
    }
  })

  it('worldDelta remains accurate after scaling', async () => {
    const { worldDeltaFromPixels } = await import('./interaction')
    const { pixelsPerUnit } = await import('@scenelab/canvas-preview')
    const resolved = resolveScene(scene, 0)
    const ppu = pixelsPerUnit(resolved) // 1 for sampleScene
    // At any display size, moving 100 scene pixels should move 100 world units when ppu=1
    // Simulate drag from base (1060,540) to (1160,540) at cssW 400: delta in scene =100
    const cssW = 400
    const { bufferW, bufferH } = getSpatialDisplayMetrics(scene, cssW, 1)
    const rect = { left: 0, top: 0, width: cssW, height: 225 }
    const start = mapClientToBase((1060 / 1920) * rect.width, (540 / 1080) * rect.height, rect, bufferW, bufferH, scene.canvas.width, scene.canvas.height, viewport)!
    const end = mapClientToBase((1160 / 1920) * rect.width, (540 / 1080) * rect.height, rect, bufferW, bufferH, scene.canvas.width, scene.canvas.height, viewport)!
    const delta = worldDeltaFromPixels(end.x - start.x, end.y - start.y, ppu)
    expect(delta.x).toBeCloseTo(100, 5)
    expect(delta.y).toBeCloseTo(0, 5)
  })
})

