args.content:
/**
 * WidgetHost — renders dynamic widgets for end-user web interfaces.
 * Floating panels are draggable windows rendered in the same React tree
 * to keep playback time synchronized. Also provides VS Code-like
 * draggable splitters for the docked left/center/right columns.
 */
import { useCallback, useRef, useState } from 'react'
import type { EventEnvelope, Scene } from '@scenelab/scene-ir'
import { PropertiesPanel } from './PropertiesPanel'
import { SpatialCanvas } from './SpatialCanvas'
import { ThreeCanvas } from './ThreeCanvas'
import { Timeline } from './timeline/Timeline'
import type { UIPanel } from './types'

type WidgetType = UIPanel['type']

export interface WidgetHostProps {
  layout: { panels: UIPanel[] } | null
  scene: Scene
  t?: number
  selectedId?: string | null
  onSelect?: (id: string | null) => void
  onEdit?: (events: EventEnvelope[]) => void
  onRemovePanel?: (id: string) => void
  width?: number
}

function SceneInfoWidget({ scene }: { scene: Scene }) {
  return (
    <div style={{ fontSize: 11, background: '#232326', padding: 8, borderRadius: 4 }}>
      <div>id: {scene.id}</div>
      <div>space: {scene.space}</div>
      <div>camera: {scene.camera.projection.type}</div>
      <div>canvas: {scene.canvas.width}x{scene.canvas.height}</div>
      <div>primitives: {scene.root.children.length}</div>
    </div>
  )
}

const MIN_W = 320
const MIN_H = 200
const DEFAULT_W = 520
const DEFAULT_H = 400
const HANDLE = 6
const CORNER = 14

type ResizeDir = 'n' | 's' | 'e' | 'w' | 'ne' | 'nw' | 'se' | 'sw'

function DraggableFloating({
  panel,
  children,
  onClose,
  initialX,
  initialY,
  renderWithWidth,
  scene,
}: {
  panel: UIPanel
  children?: React.ReactNode
  onClose?: (id: string) => void
  initialX: number
  initialY: number
  renderWithWidth?: (width: number) => React.ReactNode
  scene?: Scene
}): JSX.Element {
  const [pos, setPos] = useState({ x: initialX, y: initialY })
  const [size, setSize] = useState({ width: DEFAULT_W, height: DEFAULT_H })
  const [z, setZ] = useState(1)
  const [hover, setHover] = useState<ResizeDir | null>(null)
  const dragRef = useRef<{ startX: number; startY: number; origX: number; origY: number } | null>(null)
  const resizeRef = useRef<{ startX: number; startY: number; startW: number; startH: number; startX0: number; startY0: number; dir: ResizeDir } | null>(null)

  const onPointerDown = useCallback(
    (e: React.PointerEvent) => {
      ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
      dragRef.current = { startX: e.clientX, startY: e.clientY, origX: pos.x, origY: pos.y }
      setZ((prev) => prev + 1000)
    },
    [pos.x, pos.y],
  )

  const onPointerMove = useCallback((e: React.PointerEvent) => {
    const d = dragRef.current
    if (!d) return
    setPos({ x: d.origX + (e.clientX - d.startX), y: d.origY + (e.clientY - d.startY) })
  }, [])

  const onPointerUp = useCallback((e: React.PointerEvent) => {
    dragRef.current = null
    try { (e.target as HTMLElement).releasePointerCapture(e.pointerId) } catch {}
  }, [])

  const onResizeDown = useCallback(
    (e: React.PointerEvent, dir: ResizeDir) => {
      e.stopPropagation()
      ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
      resizeRef.current = {
        startX: e.clientX,
        startY: e.clientY,
        startW: size.width,
        startH: size.height,
        startX0: pos.x,
        startY0: pos.y,
        dir,
      }
      setZ((prev) => prev + 1000)
    },
    [pos.x, pos.y, size.height, size.width],
  )

  const onResizeMove = useCallback((e: React.PointerEvent) => {
    const r = resizeRef.current
    if (!r) return
    const dx = e.clientX - r.startX
    const dy = e.clientY - r.startY
    let newW = r.startW
    let newH = r.startH
    let newX = r.startX0
    let newY = r.startY0

    if (r.dir.includes('e')) newW = Math.max(MIN_W, r.startW + dx)
    if (r.dir.includes('s')) newH = Math.max(MIN_H, r.startH + dy)
    if (r.dir.includes('w')) {
      const candW = Math.max(MIN_W, r.startW - dx)
      newX = r.startX0 + (r.startW - candW)
      newW = candW
    }
    if (r.dir.includes('n')) {
      const candH = Math.max(MIN_H, r.startH - dy)
      newY = r.startY0 + (r.startH - candH)
      newH = candH
    }
    setSize({ width: newW, height: newH })
    if (newX !== r.startX0 || newY !== r.startY0) setPos({ x: newX, y: newY })
  }, [])

  const onResizeUp = useCallback((e: React.PointerEvent) => {
    if (resizeRef.current) {
      resizeRef.current = null
      try { (e.target as HTMLElement).releasePointerCapture(e.pointerId) } catch {}
    }
  }, [])

  const popOutExternal = useCallback(() => {
    try {
      const url = `${window.location.origin}${window.location.pathname}?view=${panel.type}`
      const w = Math.round(size.width + 40)
      const h = Math.round(size.height + 60)
      window.open(url, `scenelab-${panel.type}-${panel.id.slice(0, 8)}`, `width=${w},height=${h}`)
      onClose?.(panel.id)
    } catch {}
  }, [panel.id, panel.type, onClose, size.height, size.width])

  const innerWidthRaw = Math.max(100, size.width - 18)
  const innerHeightRaw = Math.max(100, size.height - 48)
  const isCanvasPanel = panel.type === 'scene-view' || panel.type === 'preview'
  const innerWidth = isCanvasPanel && scene
    ? Math.min(innerWidthRaw, Math.max(100, innerHeightRaw * (scene.canvas.width / scene.canvas.height)))
    : innerWidthRaw
  const content = renderWithWidth ? renderWithWidth(innerWidth) : children

  // Visible handle style helpers
  const edgeBg = (active: boolean): string => (active ? 'rgba(74,158,255,0.35)' : 'transparent')
  const cornerBg = (active: boolean): string => (active ? '#4a9eff' : '#3a3a3e')

  const EdgeHandle = ({ dir, style, cursor }: { dir: ResizeDir; style: React.CSSProperties; cursor: string }) => (
    <div
      onPointerDown={(e) => onResizeDown(e, dir)}
      onPointerMove={onResizeMove}
      onPointerUp={onResizeUp}
      onPointerEnter={() => setHover(dir)}
      onPointerLeave={() => setHover((c) => (c === dir ? null : c))}
      style={{
        position: 'absolute',
        background: edgeBg(hover === dir),
        cursor,
        touchAction: 'none',
        zIndex: 5,
        ...style,
      }}
      aria-label={`Resize ${dir}`}
      title="Drag to resize"
    >
      {/* VS Code-like grip dots */}
      <div
        style={{
          position: 'absolute',
          left: dir === 'e' || dir === 'w' ? '50%' : 0,
          top: dir === 'n' || dir === 's' ? '50%' : 0,
          transform: dir === 'e' || dir === 'w' ? 'translate(-50%, -50%)' : dir === 'n' || dir === 's' ? 'translate(-50%, -50%)' : undefined,
          width: dir === 'e' || dir === 'w' ? 2 : 24,
          height: dir === 'e' || dir === 'w' ? 24 : 2,
          background: hover === dir ? '#4a9eff' : '#555',
          borderRadius: 1,
          opacity: hover === dir ? 1 : 0.5,
          display: dir.length === 1 ? 'block' : 'none',
        }}
      />
    </div>
  )

  const CornerHandle = ({ dir, style }: { dir: ResizeDir; style: React.CSSProperties }) => (
    <div
      onPointerDown={(e) => onResizeDown(e, dir)}
      onPointerMove={onResizeMove}
      onPointerUp={onResizeUp}
      onPointerEnter={() => setHover(dir)}
      onPointerLeave={() => setHover((c) => (c === dir ? null : c))}
      style={{
        position: 'absolute',
        width: CORNER,
        height: CORNER,
        background: cornerBg(hover === dir),
        border: `1px solid ${hover === dir ? '#4a9eff' : '#444'}`,
        cursor: `${dir}-resize`,
        touchAction: 'none',
        zIndex: 6,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontSize: 10,
        color: hover === dir ? '#fff' : '#888',
        ...style,
      }}
      aria-label={`Resize ${dir}`}
      title="Drag to resize"
    >
      <span style={{ transform: dir === 'nw' ? 'rotate(-45deg)' : dir === 'ne' ? 'rotate(45deg)' : dir === 'sw' ? 'rotate(45deg)' : 'rotate(-45deg)', display: 'block' }}>⋮⋮</span>
    </div>
  )

  return (
    <div
      style={{
        position: 'fixed',
        left: pos.x,
        top: pos.y,
        zIndex: 50 + z,
        width: size.width,
        height: size.height,
        minWidth: MIN_W,
        minHeight: MIN_H,
        background: '#1e1e20',
        border: `1px solid ${hover ? '#4a9eff55' : '#444'}`,
        borderRadius: 8,
        boxShadow: '0 8px 32px rgba(0,0,0,0.6)',
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
      }}
      onPointerDown={() => setZ((p) => p + 1)}
      onPointerMove={onResizeMove}
      onPointerUp={onResizeUp}
    >
      <div
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '6px 8px',
          background: '#2a2a2e',
          cursor: 'grab',
          userSelect: 'none',
          borderBottom: '1px solid #333',
          flexShrink: 0,
        }}
      >
        <span style={{ fontSize: 11, fontWeight: 600, color: '#ccc', textTransform: 'uppercase' }}>
          {panel.type} • {panel.id.slice(0, 8)}
        </span>
        <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          <button
            onClick={(e) => { e.stopPropagation(); popOutExternal() }}
            title="Pop out to separate window — drag away from main window, live sync via BroadcastChannel"
            style={{ background: '#2d4a6a', border: '1px solid #3a5a7a', color: '#8ec7ff', cursor: 'pointer', borderRadius: 3, padding: '2px 6px', fontSize: 10 }}
          >
            ↗ Pop-out
          </button>
          <span style={{ fontSize: 10, color: '#666' }}>drag to move · drag edges to resize</span>
          {onClose && (
            <button
              onClick={() => onClose(panel.id)}
              style={{ background: '#333', border: 'none', color: '#ff8888', cursor: 'pointer', borderRadius: 3, padding: '2px 6px', fontSize: 11 }}
            >
              ✕
            </button>
          )}
        </div>
      </div>
      <div
        style={
          isCanvasPanel
            ? { padding: 8, overflow: 'auto', flex: 1, background: '#000', position: 'relative', display: 'flex', justifyContent: 'center', alignItems: 'center' }
            : { padding: 8, overflow: 'auto', flex: 1, background: '#1a1a1e', position: 'relative' }
        }
      >
        {content}
      </div>
      {/* VS Code-like border handles - all 4 edges */}
      <EdgeHandle dir="e" cursor="ew-resize" style={{ top: CORNER, right: 0, width: HANDLE, bottom: CORNER }} />
      <EdgeHandle dir="w" cursor="ew-resize" style={{ top: CORNER, left: 0, width: HANDLE, bottom: CORNER }} />
      <EdgeHandle dir="s" cursor="ns-resize" style={{ bottom: 0, left: CORNER, height: HANDLE, right: CORNER }} />
      <EdgeHandle dir="n" cursor="ns-resize" style={{ top: 0, left: CORNER, height: HANDLE, right: CORNER }} />
      {/* Corners */}
      <CornerHandle dir="se" style={{ right: 0, bottom: 0, borderTopLeftRadius: 6, borderBottomRightRadius: 8 }} />
      <CornerHandle dir="sw" style={{ left: 0, bottom: 0, borderTopRightRadius: 6, borderBottomLeftRadius: 8 }} />
      <CornerHandle dir="ne" style={{ right: 0, top: 0, borderBottomLeftRadius: 6, borderTopRightRadius: 8 }} />
      <CornerHandle dir="nw" style={{ left: 0, top: 0, borderBottomRightRadius: 6, borderTopLeftRadius: 8 }} />
    </div>
  )
}

export function WidgetHost({ layout, scene, t = 0, selectedId, onSelect, onEdit, onRemovePanel, width = 320 }: WidgetHostProps): JSX.Element {
  // VS Code-like splitters for docked columns
  const [leftW, setLeftW] = useState(width)
  const [rightW, setRightW] = useState(width)
  const [dragging, setDragging] = useState<'left' | 'right' | null>(null)
  const leftStartRef = useRef<{ x: number; w: number } | null>(null)
  const rightStartRef = useRef<{ x: number; w: number } | null>(null)

  const onLeftDown = useCallback((e: React.PointerEvent) => {
    ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
    leftStartRef.current = { x: e.clientX, w: leftW }
    setDragging('left')
  }, [leftW])
  const onRightDown = useCallback((e: React.PointerEvent) => {
    ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
    rightStartRef.current = { x: e.clientX, w: rightW }
    setDragging('right')
  }, [rightW])

  const onDockMove = useCallback((e: React.PointerEvent) => {
    if (dragging === 'left' && leftStartRef.current) {
      const dx = e.clientX - leftStartRef.current.x
      setLeftW(Math.max(220, Math.min(600, leftStartRef.current.w + dx)))
    } else if (dragging === 'right' && rightStartRef.current) {
      const dx = e.clientX - rightStartRef.current.x
      setRightW(Math.max(220, Math.min(600, rightStartRef.current.w - dx)))
    }
  }, [dragging])

  const onDockUp = useCallback((e: React.PointerEvent) => {
    leftStartRef.current = null
    rightStartRef.current = null
    setDragging(null)
    try { (e.target as HTMLElement).releasePointerCapture(e.pointerId) } catch {}
  }, [])

  if (!layout) return <div style={{ fontSize: 12, color: '#666' }}>No UI layout (standalone) — click “+ scene-view” to spawn a floating resizable window</div>

  const renderPanel = (panel: UIPanel, availWidth?: number) => {
    const w = availWidth ?? width
    const type = panel.type as WidgetType
    switch (type) {
      case 'project':
        return <div style={{ fontSize: 11, color: '#888' }}>Project — {JSON.stringify(panel.props)}</div>
      case 'scene':
        return <SceneInfoWidget scene={scene} />
      case 'outliner':
        return (
          <div style={{ fontSize: 11 }}>
            {scene.root.children.map((c: any) => (
              <div key={c.id} style={{ padding: '2px 0' }}>
                <button onClick={() => onSelect?.(c.id)} style={{ background: 'none', border: 'none', color: selectedId === c.id ? '#8ec7ff' : '#ccc', cursor: 'pointer' }}>
                  {c.word} ({c.id})
                </button>
              </div>
            ))}
          </div>
        )
      case 'scene-view':
        return (
          <div>
            {scene.space === '3d' || scene.camera.projection.type === 'perspective' ? (
              <ThreeCanvas scene={scene} t={t} width={w} editableCamera={true} selectedId={selectedId} onSelect={onSelect} config={{ sessionId: 'demo' }} />
            ) : (
              <SpatialCanvas scene={scene} selectedId={selectedId} onSelect={onSelect} onEdit={onEdit} width={w} t={t} config={{ sessionId: 'demo' }} />
            )}
          </div>
        )
      case 'preview':
        return (
          <div>
            <ThreeCanvas scene={scene} t={t} width={w} editableCamera={false} selectedId={selectedId} onSelect={onSelect} config={{ sessionId: 'demo' }} />
            <div style={{ fontSize: 10, color: '#666', marginTop: 4 }}>Preview — scene camera locked (final output)</div>
          </div>
        )
      case 'properties':
        return <PropertiesPanel scene={scene} selectedId={selectedId ?? null} onEdit={onEdit} config={{ sessionId: 'demo' }} />
      case 'timeline':
        return <Timeline scene={scene} t={t} onChange={() => {}} width={w} onEdit={onEdit} config={{ sessionId: 'demo' }} />
      case 'trace':
        return <div style={{ fontSize: 11, color: '#777' }}>Trace — {scene.id}</div>
      default:
        return <div style={{ fontSize: 11, color: '#666' }}>Unknown: {String(type)}</div>
    }
  }

  const left = layout.panels.filter((p) => p.position === 'left')
  const center = layout.panels.filter((p) => p.position === 'center')
  const right = layout.panels.filter((p) => p.position === 'right')
  const floating = layout.panels.filter((p) => !p.position || p.position === 'floating')

  const Gutter = ({ side }: { side: 'left' | 'right' }) => (
    <div
      onPointerDown={side === 'left' ? onLeftDown : onRightDown}
      onPointerMove={onDockMove}
      onPointerUp={onDockUp}
      style={{
        width: 6,
        cursor: 'col-resize',
        background: dragging === side ? '#4a9eff' : '#2a2a2e',
        borderLeft: '1px solid #333',
        borderRight: '1px solid #333',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        userSelect: 'none',
        touchAction: 'none',
      }}
      title="Drag to resize"
    >
      <div style={{ width: 2, height: 24, background: dragging === side ? '#fff' : '#555', borderRadius: 1 }} />
    </div>
  )

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }} onPointerMove={onDockMove} onPointerUp={onDockUp}>
      <div style={{ display: 'flex', gap: 0, flexWrap: 'nowrap', alignItems: 'stretch' }}>
        {left.length > 0 && (
          <>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8, width: leftW, flexShrink: 0 }}>
              <div style={{ fontSize: 10, color: '#888', textTransform: 'uppercase' }}>Left — drag gutter to resize</div>
              {left.map((p) => (
                <div key={p.id} style={{ border: '1px solid #333', borderRadius: 6, padding: 8 }}>
                  <div style={{ fontSize: 10, color: '#666', marginBottom: 4 }}>{p.type} ({p.id})</div>
                  {renderPanel(p, leftW - 18)}
                </div>
              ))}
            </div>
            <Gutter side="left" />
          </>
        )}
        {center.length > 0 && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8, flex: 1, minWidth: 200 }}>
            <div style={{ fontSize: 10, color: '#888', textTransform: 'uppercase' }}>Center</div>
            {center.map((p) => (
              <div key={p.id} style={{ border: '1px solid #333', borderRadius: 6, padding: 8 }}>
                <div style={{ fontSize: 10, color: '#666', marginBottom: 4 }}>{p.type} ({p.id})</div>
                {renderPanel(p)}
              </div>
            ))}
          </div>
        )}
        {right.length > 0 && (
          <>
            <Gutter side="right" />
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8, width: rightW, flexShrink: 0 }}>
              <div style={{ fontSize: 10, color: '#888', textTransform: 'uppercase' }}>Right — drag gutter to resize</div>
              {right.map((p) => (
                <div key={p.id} style={{ border: '1px solid #333', borderRadius: 6, padding: 8 }}>
                  <div style={{ fontSize: 10, color: '#666', marginBottom: 4 }}>{p.type} ({p.id})</div>
                  {renderPanel(p, rightW - 18)}
                </div>
              ))}
            </div>
          </>
        )}
        {left.length === 0 && center.length === 0 && right.length === 0 && (
          <div style={{ fontSize: 11, color: '#666', padding: 12, border: '1px dashed #333', borderRadius: 6 }}>
            No docked panels — spawn floating windows via the “+” buttons above. Floating windows are now <b>draggable</b> (title bar) and <b>resizable</b> (drag any edge/corner, like VS Code).
          </div>
        )}
      </div>

      {floating.length > 0 && (
        <>
          {floating.map((p, idx) => (
            <DraggableFloating key={p.id} panel={p} onClose={onRemovePanel} initialX={100 + idx * 40} initialY={100 + idx * 40} renderWithWidth={(w) => renderPanel(p, w)} scene={scene} />
          ))}
        </>
      )}
    </div>
  )
}

