function VGutter({ onDelta }: { onDelta: (dy: number) => void }): JSX.Element {
  const [hover, setHover] = useState(false)
  const [dragging, setDragging] = useState(false)
  const startRef = useRef<{ y: number } | null>(null)
  const onPointerDown = useCallback((e: React.PointerEvent) => {
    ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
    startRef.current = { y: e.clientY }
    setDragging(true)
  }, [])
  const onPointerMove = useCallback((e: React.PointerEvent) => {
    if (!startRef.current) return
    const dy = e.clientY - startRef.current.y
    startRef.current.y = e.clientY
    onDelta(dy)
  }, [onDelta])
  const onPointerUp = useCallback((e: React.PointerEvent) => {
    startRef.current = null
    setDragging(false)
    try { (e.target as HTMLElement).releasePointerCapture(e.pointerId) } catch {}
  }, [])
  return (
    <div
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerEnter={() => setHover(true)}
      onPointerLeave={() => { if (!dragging) setHover(false) }}
      style={{
        height: 6,
        flexShrink: 0,
        background: dragging ? '#4a9eff' : hover ? '#3a5a7a' : '#2a2a2e',
        cursor: 'row-resize',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        borderTop: '1px solid #333',
        borderBottom: '1px solid #333',
        touchAction: 'none',
        userSelect: 'none',
      }}
      title="Drag to resize (like VS Code)"
    >
      <div style={{ width: 24, height: 2, background: dragging ? '#fff' : hover ? '#8ec7ff' : '#555', borderRadius: 1 }} />
    </div>
  )
}

